from itertools import product

def manhattan_dist(a, b):
    return abs(a[0] - b[0]) + abs(a[1] - b[1])

def get_layer_cells(center, dist):
    cells = []
    for r in range(17):
        for c in range(19):
            if manhattan_dist((r,c), center) == dist:
                cells.append((r,c))
    return cells

# 3s at these positions
centers = [(3,4), (8,11), (13,6)]

# Build grid
grid = [[0]*19 for _ in range(17)]

# Place 8s at distance 3 from each 3
for center in centers:
    for r,c in get_layer_cells(center, 3):
        if not grid[r][c]:  # Oppose existing layers
            grid[r][c] = 8

# Place 2s at distance 2 from each 3
for center in centers:
    for r,c in get_layer_cells(center, 2):
        if not grid[r][c]:  # Place on non-8 cells
            grid[r][c] = 2

# Place 3s
for r,c in centers:
    grid[r][c] = 3

# Convert to list of lists
output = grid
print("Layer positions:")
for center in centers:
    print(f"{center}: dist3=", get_layer_cells(center, 3), "dist2=", get_layer_cells(center, 2))
print("\nOutput grid:")
for row in output:
    print(row)
